// Raymarched metaball blob — slow morph, key + rim lighting
uniform float uSpeed;     // @param 0.4 0 3
uniform float uBlend;     // @param 0.45 0.05 1.5
uniform float uSize;      // @param 0.42 0.15 0.8
uniform vec3  uBase;      // @param #3A2A8C
uniform vec3  uKey;       // @param #FFE2C0
uniform float uKeyGain;   // @param 1.2 0 3
uniform vec3  uRim;       // @param #3FD8FF
uniform float uRimGain;   // @param 1.4 0 4
uniform float uRimPower;  // @param 3.0 0.5 8
uniform vec3  uBg;        // @param #07070C

struct Hit {
  bool  hit;
  float t;
  vec3  pos;
  int   steps;
};

float smin(float a, float b, float k) {
  float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
  return mix(b, a, h) - k * h * (1.0 - h);
}

float map(vec3 q) {
  float t = iTime * uSpeed;
  float d = 1e5;
  for (int i = 0; i < 5; i++) {
    float fi = float(i);
    vec3 c = vec3(
      sin(t * (0.70 + 0.13 * fi) + fi * 1.7),
      cos(t * (0.50 + 0.11 * fi) + fi * 2.3),
      sin(t * (0.60 + 0.09 * fi) + fi * 0.9)
    ) * vec3(0.7, 0.5, 0.5);
    float r = uSize + 0.08 * sin(t * 1.3 + fi * 2.1);
    d = smin(d, length(q - c) - r, uBlend);
  }
  return d;
}

vec3 calcNormal(vec3 q) {
  const vec2 e = vec2(1.0, -1.0) * 0.0012;
  return normalize(e.xyy * map(q + e.xyy) + e.yyx * map(q + e.yyx) +
                   e.yxy * map(q + e.yxy) + e.xxx * map(q + e.xxx));
}

Hit march(vec3 ro, vec3 rd) {
  Hit h;
  h.hit = false;
  h.t = 0.0;
  h.pos = ro;
  h.steps = 0;
  for (int i = 0; i < 110; i++) {
    h.pos = ro + rd * h.t;
    float d = map(h.pos);
    h.steps = i;
    if (d < 0.0008 * h.t + 0.0005) { h.hit = true; break; }
    h.t += d * 0.9;
    if (h.t > 12.0) break;
  }
  return h;
}

void main() {
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  float t = iTime * uSpeed;

  vec3 ro = vec3(0.0, 0.0, 3.6);
  ro.xz *= rot(0.15 * sin(t * 0.3));
  vec3 fw = normalize(-ro);
  vec3 rt = normalize(cross(fw, vec3(0.0, 1.0, 0.0)));
  vec3 up = cross(rt, fw);
  vec3 rd = normalize(p.x * rt + p.y * up + 1.6 * fw);

  // Background: soft vertical gradient + faint glow
  vec3 col = uBg * (1.0 + 0.6 * (0.5 - uv.y));
  col += uRim * 0.05 * exp(-3.0 * dot(p, p));

  Hit h = march(ro, rd);
  if (h.hit) {
    vec3 n = calcNormal(h.pos);
    vec3 v = -rd;

    vec3 keyDir = normalize(vec3(0.6, 0.7, 0.55));
    vec3 rimDir = normalize(vec3(-0.7, 0.35, -0.6));

    float diff = max(dot(n, keyDir), 0.0);
    float wrap = max((dot(n, keyDir) + 0.3) / 1.3, 0.0);
    vec3 hv = normalize(keyDir + v);
    float spec = pow(max(dot(n, hv), 0.0), 64.0) * diff;

    float fres = pow(1.0 - max(dot(n, v), 0.0), uRimPower);
    float rimMask = clamp(dot(n, rimDir) + 0.6, 0.0, 1.0);
    float rim = fres * rimMask;

    float ao = clamp(1.0 - float(h.steps) / 110.0, 0.0, 1.0);
    ao = mix(0.55, 1.0, ao);
    float amb = 0.5 + 0.5 * n.y;

    vec3 surf = uBase * (0.12 * amb + 0.9 * wrap * uKey * uKeyGain);
    surf += uKey * spec * uKeyGain * 0.9;
    surf *= ao;
    surf += uRim * rim * uRimGain;

    float fog = exp(-0.04 * h.t * h.t);
    col = mix(col, surf, fog);
  }

  float vig = 1.0 - 0.45 * dot(p, p);
  col *= vig;
  col = col / (1.0 + col);          // tonemap
  col = pow(col, vec3(1.0 / 2.2));  // gamma
  fragColor = vec4(col, 1.0);
}
